∀ {α : Type u_1} {r : α → α → Prop} {motive : (a a_1 : List α) → Giallar.Scheduling.IndependentPerm r a a_1 → Prop}
  (a : α) {l₁ l₂ : List α} (a_1 : Giallar.Scheduling.IndependentPerm r l₁ l₂),
  Giallar.Scheduling.IndependentPerm.below a_1 → motive l₁ l₂ a_1 → Giallar.Scheduling.IndependentPerm.below ⋯

∀ {Task : Type u_1} {M : Type u_2} [inst : Monoid M] {sem : Task → M} {rank : Task → ℕ} {b : ℕ}
  {primitive : Task → Prop} {s s' : Giallar.Worklist.State Task M},
  Giallar.Worklist.Step sem rank b primitive s s' → Giallar.Worklist.meaning sem s' = Giallar.Worklist.meaning sem s

∀ {ι : Type u_1} [inst : Fintype ι] [inst_1 : DecidableEq ι] [inst_2 : Nonempty ι] {m : ℕ}
  (H : ↥(unitary (Matrix ι ι ℂ))) (masks : Fin m → ι → Bool) (b : ℕ),
  ∀ p ∈ Giallar.ControlledPhase.rowPairs H masks b, ‖p.1‖ ≤ 1 ∧ ‖p.2‖ ≤ 1

∀ {W : Type u_1} {Gate : Type u_2} [inst : Fintype W] [inst_1 : DecidableEq W] (G : SimpleGraph W)
  (support : Gate → Giallar.Routing.Support W) (hG : G.Connected) (x : List Gate) (x_1 : Equiv.Perm W),
  Giallar.Routing.routeCircuit G support hG x x_1 =
    match x, x_1 with
    | [], p => ([], p)
    | g :: src, p =>
      have swaps := Giallar.Routing.gateFallback G support hG p g;
      have q := Giallar.Routing.swapLayout swaps * p;
      have result := Giallar.Routing.routeCircuit G support hG src q;
      (Giallar.Routing.swapActions swaps ++ Giallar.Routing.Action.emit q g :: result.1, result.2)

∀ {Q : Type u_2} {perm : Equiv.Perm (Giallar.PhasePolynomial.Bits Q)} {phase : Giallar.PhasePolynomial.Bits Q → ℝ}
  {perm_1 : Equiv.Perm (Giallar.PhasePolynomial.Bits Q)} {phase_1 : Giallar.PhasePolynomial.Bits Q → ℝ},
  { perm := perm, phase := phase } = { perm := perm_1, phase := phase_1 } → perm = perm_1 ∧ phase = phase_1

∀ {Q : Type u_1} [inst : DecidableEq Q] (r : Giallar.PhasePolynomial.Representation Q) (c t : Q) (h : c ≠ t),
  r.step (Giallar.PhasePolynomial.Gate.cx c t h) =
    { linear := r.linear.trans (Giallar.PhasePolynomial.cnot c t h), terms := r.terms }

∀ {Task : Type u_1} {M : Type u_2} [inst : Monoid M] {sem : Task → M} {rank : Task → ℕ} {b : ℕ}
  {primitive : Task → Prop}
  {motive :
    (a : Giallar.Worklist.State Task M) →
      (a_1 : ℕ) → (a_2 : Giallar.Worklist.State Task M) → Giallar.Worklist.Steps sem rank b primitive a a_1 a_2 → Prop}
  {a : Giallar.Worklist.State Task M} {a_1 : ℕ} {a_2 : Giallar.Worklist.State Task M}
  (t : Giallar.Worklist.Steps sem rank b primitive a a_1 a_2),
  (∀ (a : Giallar.Worklist.State Task M) (a_3 : ℕ) (a_4 : Giallar.Worklist.State Task M)
      (t : Giallar.Worklist.Steps sem rank b primitive a a_3 a_4),
      Giallar.Worklist.Steps.below t → motive a a_3 a_4 t) →
    motive a a_1 a_2 t

∀ {W : Type u_1},
  Giallar.Routing.wireBits =
    {
      toFun := fun p =>
        { toFun := fun x i => x ((Equiv.symm p) i), invFun := fun x i => x (p i), left_inv := ⋯, right_inv := ⋯ },
      map_one' := ⋯, map_mul' := ⋯ }

∀ {Ω : Type u_2} {inst : MeasurableSpace Ω} {survival : ℕ → Set Ω}
  {measurable_survival : ∀ (n : ℕ), MeasurableSet (survival n)} {survival_zero : survival 0 = Set.univ}
  {antitone_survival : Antitone survival} {survival_1 : ℕ → Set Ω}
  {measurable_survival_1 : ∀ (n : ℕ), MeasurableSet (survival_1 n)} {survival_zero_1 : survival_1 0 = Set.univ}
  {antitone_survival_1 : Antitone survival_1},
  { survival := survival, measurable_survival := measurable_survival, survival_zero := survival_zero,
        antitone_survival := antitone_survival } =
      { survival := survival_1, measurable_survival := measurable_survival_1, survival_zero := survival_zero_1,
        antitone_survival := antitone_survival_1 } →
    survival = survival_1

∀ {Q : Type u_1} [inst : DecidableEq Q] (c : Giallar.PhasePolynomial.LinearCircuit Q),
  Giallar.PhasePolynomial.execute c.gates Giallar.PhasePolynomial.Action.one =
    { perm := c.linear.toEquiv, phase := fun x => 0 }

