∀ {n m : ℕ} (P : Giallar.Certificates.System n m) (a : Fin n → ℚ) (b : ℚ),
  P.prepend a b =
    { coeff := fun i => Fin.cases (motive := fun x => Fin n → ℚ) a P.coeff i, rhs := fun i => Fin.cases b P.rhs i }

∀ {ι : Type u_1} [inst : Fintype ι] [inst_1 : DecidableEq ι] [inst_2 : Nonempty ι] {m : ℕ}
  (H : ↥(unitary (Matrix ι ι ℂ))) (masks : Fin m → ι → Bool) (b : ℕ),
  (List.map (fun p => ‖p.1 - p.2‖) (Giallar.ControlledPhase.rowPairs H masks b)).sum ≤ 2 * Real.pi / 2 ^ b

