∀ {Task : Type u_1} {M : Type u_2} {inst : Monoid M} {sem : Task → M} {rank : Task → ℕ} {b : ℕ} {t : Task}
  {children : List Task} {length_le : children.length ≤ b} {rank_lt : ∀ u ∈ children, rank u < rank t}
  {sound : Giallar.Worklist.eval sem children = sem t} {children_1 : List Task} {length_le_1 : children_1.length ≤ b}
  {rank_lt_1 : ∀ u ∈ children_1, rank u < rank t} {sound_1 : Giallar.Worklist.eval sem children_1 = sem t},
  { children := children, length_le := length_le, rank_lt := rank_lt, sound := sound } =
      { children := children_1, length_le := length_le_1, rank_lt := rank_lt_1, sound := sound_1 } →
    children = children_1

∀ {n : ℕ} {start duration : Fin n → ℝ} {intervals : ℕ} {cuts : ℕ → ℝ} {lo hi : Fin n → ℕ}
  {mono : StrictMonoOn cuts (Set.Icc 0 intervals)} {lo_le : ∀ (v : Fin n), lo v ≤ intervals}
  {hi_le : ∀ (v : Fin n), hi v ≤ intervals} {cut_lo : ∀ (v : Fin n), cuts (lo v) = start v}
  {cut_hi : ∀ (v : Fin n), cuts (hi v) = start v + duration v} {intervals_1 : ℕ} {cuts_1 : ℕ → ℝ}
  {lo_1 hi_1 : Fin n → ℕ} {mono_1 : StrictMonoOn cuts_1 (Set.Icc 0 intervals_1)}
  {lo_le_1 : ∀ (v : Fin n), lo_1 v ≤ intervals_1} {hi_le_1 : ∀ (v : Fin n), hi_1 v ≤ intervals_1}
  {cut_lo_1 : ∀ (v : Fin n), cuts_1 (lo_1 v) = start v}
  {cut_hi_1 : ∀ (v : Fin n), cuts_1 (hi_1 v) = start v + duration v},
  { intervals := intervals, cuts := cuts, lo := lo, hi := hi, mono := mono, lo_le := lo_le, hi_le := hi_le,
        cut_lo := cut_lo, cut_hi := cut_hi } =
      { intervals := intervals_1, cuts := cuts_1, lo := lo_1, hi := hi_1, mono := mono_1, lo_le := lo_le_1,
        hi_le := hi_le_1, cut_lo := cut_lo_1, cut_hi := cut_hi_1 } →
    intervals = intervals_1 ∧ cuts = cuts_1 ∧ lo = lo_1 ∧ hi = hi_1

