∀ {Task : Type u_1} {M : Type u_2} [inst : Monoid M] {sem : Task → M} {rank : Task → ℕ} {b : ℕ}
  {primitive : Task → Prop}
  {motive : (a a_1 : Giallar.Worklist.State Task M) → Giallar.Worklist.Step sem rank b primitive a a_1 → Prop}
  {a a_1 : Giallar.Worklist.State Task M} (t : Giallar.Worklist.Step sem rank b primitive a a_1),
  (∀ (t : Task) (ts : List Task) (w : M) (h : primitive t),
