∀ {W : Type u_1} {Gate : Type u_2} [inst : DecidableEq W] (plan : Equiv.Perm W → Gate → List (W × W)) (x : List Gate)
  (x_1 : Equiv.Perm W),
  Giallar.Routing.routePlan plan x x_1 =
    match x, x_1 with
    | [], p => ([], p)
    | g :: src, p =>
      have swaps := plan p g;
      have q := Giallar.Routing.swapLayout swaps * p;
      have result := Giallar.Routing.routePlan plan src q;
      (Giallar.Routing.swapActions swaps ++ Giallar.Routing.Action.emit q g :: result.1, result.2)
